 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg for _ in range(w)] for _ in range(h)]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            minr = min(y for y, x in cells); maxr = max(y for y, x in cells)
            minc = min(x for y, x in cells); maxc = max(x for y, x in cells)
            area = (maxr-minr+1) * (maxc-minc+1)
            # Large, approximately rectangular color patches are the objects;
            # isolated speckles and the surrounding distractors are discarded.
            if area >= 8 and len(cells) / area >= 0.65:
                for y in range(minr, maxr+1):
                    for x in range(minc, maxc+1):
                        out[y][x] = color
    return out


if __name__ == '__main__':
    pass
